  8236  /* Removes the protocols that require consistency between match and actions
  8237   * (that's everything but OpenFlow 1.0) from '*usable_protocols'.
  8238   *
  8239   * (An example of an inconsistency between match and actions is a flow that
  8240   * does not match on an MPLS Ethertype but has an action that pops an MPLS
  8241   * label.) */
  8242  static void
  8243  inconsistent_match(enum ofputil_protocol *usable_protocols)
  8244  {
  8245      *usable_protocols &= OFPUTIL_P_OF10_ANY;
  8246  }
  8247
  8248  /* May modify flow->packet_type, flow->dl_type, flow->nw_proto and
  8249   * flow->vlan_tci, caller must restore them.
  8250   *
  8251   * Modifies some actions, filling in fields that could not be properly set
  8252   * without context. */
  8253  static enum ofperr
  8254  ofpact_check__(struct ofpact *a, struct ofpact_check_params *cp)
  8255  {
  8256      switch (a->type) {
  8257  #define OFPACT(ENUM, STRUCT, MEMBER, NAME)                  \
  8258          case OFPACT_##ENUM:                                 \
  8259              return check_##ENUM(ofpact_get_##ENUM(a), cp);
  8260          OFPACTS
  8261  #undef OFPACT
  8262      default:
  8263          OVS_NOT_REACHED();
  8264      }
  8265  }
  8266
  8267  /* Checks that the 'ofpacts_len' bytes of actions in 'ofpacts' are
  8268   * appropriate for a packet with the prerequisites satisfied by 'flow' in a
  8269   * switch with no more than 'max_ports' ports.
  8270   *
  8271   * If 'ofpacts' and 'flow' are inconsistent with one another, un-sets in
  8272   * '*usable_protocols' the protocols that forbid the inconsistency.  (An
  8273   * example of an inconsistency between match and actions is a flow that does
  8274   * not match on an MPLS Ethertype but has an action that pops an MPLS label.)
  8275   *
  8276   * May annotate ofpacts with information gathered from the 'match'.
  8277   *
  8278   * May temporarily modify 'match', but restores the changes before
  8279   * returning. */
  8280  enum ofperr
  8281  ofpacts_check(struct ofpact ofpacts[], size_t ofpacts_len,
  8282                struct ofpact_check_params *cp)
  8283  {
  8284      /* Save fields that might temporarily be modified. */
  8285      struct flow *flow = &cp->match->flow;
  8286      ovs_be32 packet_type = flow->packet_type;
  8287      ovs_be16 dl_type = flow->dl_type;
  8288      uint8_t nw_proto = flow->nw_proto;
  8289      union flow_vlan_hdr vlans[FLOW_MAX_VLAN_HEADERS];
  8290      memcpy(vlans, flow->vlans, sizeof vlans);
  8291
  8292      /* Check all the actions. */
  8293      cp->usable_protocols = OFPUTIL_P_ANY;
  8294      enum ofperr error = 0;
  8295      struct ofpact *a;
  8296      OFPACT_FOR_EACH (a, ofpacts, ofpacts_len) {
  8297          error = ofpact_check__(a, cp);
  8298          if (error) {
  8299              break;
  8300          }
  8301      }
  8302
  8303      /* Restore fields that may have been modified. */
  8304      flow->packet_type = packet_type;
  8305      flow->dl_type = dl_type;
  8306      memcpy(flow->vlans, vlans, sizeof vlans);
  8307      flow->nw_proto = nw_proto;
  8308
  8309      return error;
  8310  }
